INSERT OR REPLACE INTO user_content (id, share_code, lesson_id, kind, payload, created_at, updated_at) VALUES ('demo-cn-l16-001', 'demo', 'l16', 'note', '{"id": "cn-l16-001", "title": "于勒与杨二嫂——信任与温情如何被侵蚀", "body": "于勒是资本主义社会的失败者：人的价值由钱决定——有钱是亲戚，没钱连亲妈都不敢认，亲情变成交易。《故乡》里的杨二嫂，则折射中国乡村社会变迁中人被物化、标签化，人际关系变质。两篇对照，核心都是人与人之间的信任和温情被侵蚀。复习时可抓住「金钱/身份如何改写亲情与邻里关系」这条比较线。", "tags": ["比较阅读", "于勒", "杨二嫂", "亲情"], "createdAt": "2026-10-17T13:00:00+08:00"}', '2026-10-17T13:00:00+08:00', '2026-10-17T13:00:00+08:00');
INSERT OR REPLACE INTO user_content (id, share_code, lesson_id, kind, payload, created_at, updated_at) VALUES ('demo-st-l16-001', 'demo', 'l16', 'task', '{"id": "st-l16-001", "title": "读书辩论会——「若于勒真的发财，菲利普夫妇会怎么样？」", "prompt": "请结合课文伏笔与人物言行，分正反方各谈两点。每点写清「观点」与「原文依据」，避免空喊口号。", "sides": {"pro": [{"claim": "发财后会热情迎接，亲情似乎「恢复」——此前的冷漠主要源于经济压力。", "evidence": "依据：听说于勒在美洲发财时，全家人日夜盼他归来、把他写成「福音书」；若瑟夫父母的「希望」与金钱消息同步升温，说明态度变化与「有没有钱」强绑定。若真发财，按同一逻辑，迎接与夸奖会立刻回来。"}, {"claim": "年轻一代（如若瑟夫）可能真心欢迎，作品也留出人性善良的一面。", "evidence": "依据：船上认出穷水手于勒后，「我」仍偷偷给了他十个铜子的小费，并感到心酸——少年视角尚存同情。辩论可引申：即便父母势利，年轻人未必完全被金钱标准吞没，发财情境下更可能流露真诚欢迎。"}], "con": [{"claim": "即使发财，势利眼光不会变——他们看重的是身份来历与面子，而非真正的亲情。", "evidence": "依据：于勒被称作「全家的恐怖」时，是因其败家与拖累；「发财」传说让他变成「好心的于勒」，标签随利益翻转。说明亲情服从于「是否体面、是否有利」，发财只是换了一块更光鲜的标签，本质仍是势利。"}, {"claim": "结尾见穷困于勒就躲开，说明金钱标准已内化；发财与否只是表面，遇「不利」仍会划清界限。", "evidence": "依据：船长证实卖牡蛎的正是于勒后，菲利普夫妇立刻变脸、下令躲开，生怕被认作亲戚、影响女儿婚事。可见评价标准已内化为「金钱/面子」；即便假设他发财，一旦出现更「不合算」的风险，同样可能抛弃。伏笔（信件、夸赞）与结局（躲避）对照，强化批判。"}]}, "createdAt": "2026-10-17T13:05:00+08:00", "chatTurns": [{"side": "pro", "text": "我说啊，要是于勒真发财了，菲利普夫妇八成会热情迎接——之前那么冷，主要是家里穷、压力大。一听说他在美洲发财，全家就日夜盼、把他写成「福音书」；态度跟着钱走。钱有了，盼和赞那套逻辑不就回来了？"}, {"side": "con", "text": "别天真。势利是他们的性格和价值观，不是账本算平了就能改。于勒败家时是「全家的恐怖」，传说发财就变「好心的于勒」——标签跟着利益翻。他们看重的是身份、来历和面子，不是真亲情。发财也只是换块更光鲜的标签。"}, {"side": "pro", "text": "那年轻人呢？若瑟夫（「我」）未必完全被金钱标准同化。船上认出穷水手后，他还偷偷给了十个铜子小费，心里发酸——少年视角里还有同情。就算父母势利，发财情境下年轻人更可能真心欢迎。"}, {"side": "con", "text": "可结尾他们一确认是穷于勒就躲开，生怕影响女儿婚事——金钱标准早就内化了。发财与否只是表面；一旦「不合算」，照样划清界限。信件里的夸赞和结局的躲避一对照，批判更清楚：即使真发财，也未必真正尊重他这个人。"}]}', '2026-10-17T13:05:00+08:00', '2026-10-17T13:05:00+08:00');
INSERT OR REPLACE INTO user_content (id, share_code, lesson_id, kind, payload, created_at, updated_at) VALUES ('cn-l16-001', 'builtin', 'l16', 'note', '{"id": "cn-l16-001", "title": "于勒与杨二嫂——信任与温情如何被侵蚀", "body": "于勒是资本主义社会的失败者：人的价值由钱决定——有钱是亲戚，没钱连亲妈都不敢认，亲情变成交易。《故乡》里的杨二嫂，则折射中国乡村社会变迁中人被物化、标签化，人际关系变质。两篇对照，核心都是人与人之间的信任和温情被侵蚀。复习时可抓住「金钱/身份如何改写亲情与邻里关系」这条比较线。", "tags": ["比较阅读", "于勒", "杨二嫂", "亲情"], "createdAt": "2026-10-17T13:00:00+08:00"}', '2026-10-17T13:00:00+08:00', '2026-10-17T13:00:00+08:00');
